```javascript
function addPoly(a, b) {
    const len = Math.max(a.length, b.length);
    const result = [];
    for (let i = 0; i < len; i++) {
        const ca = i < a.length ? a[i] : 0;
        const cb = i < b.length ? b[i] : 0;
        result.push(ca + cb);
    }
    return result;
}

function main() {
    // A(x) = 3x^2 + 2x + 1  → [1, 2, 3] (인덱스=차수)
    const a = [1, 2, 3];
    // B(x) = x^2 + 4        → [4, 0, 1]
    const b = [4, 0, 1];

    const c = addPoly(a, b); // 4x^2 + 2x + 5
    let output = "";
    for (let i = c.length - 1; i >= 0; i--)
        if (c[i] !== 0) output += `${c[i]}x^${i} `;
    console.log(output); // 4x^2 2x^1 5x^0
}

main();
